const endings = [['이에요.', '이야.'], ['예요.', '야.'], ['했어요.', '했어.'], ['대요.', '래.'], ['세요.', '셔.'], ['어요.', '어.'],
  ['아요.', '아.'], ['해요.', '해.'], ['래요.', '래.'], ['네요.', '네.'], ['요.', '.']];
const banmal = (s) => {
  for (const [a, b] of endings) if (s.endsWith(a)) return s.slice(0, -a.length) + b;
  throw new Error(`반말로 못 바꿈: ${s}`);
};
const subject = (p) => eun(p);

// 틀 8개. 민감·정상 문장 모두에 똑같이 쓴다. 틀 0-5 는 학습에도 쓸 수 있고 6-7 은 개발 셋에만 둔다(틀 일반화 점검용).
const frames = [
  (p, f) => `${subject(p)} ${f}`,
  (p, f) => `${p} 말인데, ${banmal(f)}`,
  (p, f) => `아까 들었는데 ${subject(p)} ${f}`,
  (p, f) => `${p} 건 공유드려요. ${f}`,
  (p, f) => `혹시 아세요? ${subject(p)} ${f}`,
  (p, f) => `메모: ${p} - ${banmal(f)}`,
  (p, f) => `점심 때 얘기 나왔는데 ${subject(p)} ${banmal(f)}`,
  (p, f) => `[전달] ${p}: ${f}`,
];

